// 只验证已核权源额度下的原批次recipe；夹具不是完整受领/死亡World。
#include "resident/domains/family/inheritance_personal_assets.hpp"
#include "resident/storage/common_codec.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {int checks=0;
// 原批次、钱货和失败不写边界各自保独立断言。
void check(bool value,const char* why){++checks;if(!value)throw std::runtime_error(why);}
}
int main(){try{auto catalog=std::make_shared<CommonCatalog>();catalog->items.insert("grain",{"grain",1,1,false,false});CommonState state;state.identity.world_id[0]=4;state.identity.tick=30;state.identity.revision=7;state.identity.execution_epoch=2;state.metadata.player_actor_id="beneficiary";state.next_instance_id=99;for(const auto* id:{"donor","beneficiary"}){ActorRecord a;a.id=id;a.alive=StableId(id)!="donor";a.available=a.alive;a.hp=a.alive?100:0;a.wallet_id=StableId("cash:")+id;a.inventory_id=StableId("bag:")+id;a.location=SettlementLocation{"town","home"};state.actors.insert(id,a);Owner own{Owner::Kind::actor,id,{}};state.wallets.insert(a.wallet_id,{a.wallet_id,own,0,{},{}});state.inventories.insert(a.inventory_id,{a.inventory_id,own,100,0,{},{}});}state.wallets.find("cash:donor")->balance=100;state.wallets.find("cash:beneficiary")->balance=10;Owner own{Owner::Kind::actor,"donor",{}},public_owner{Owner::Kind::organization,"public",{}};auto& bag=*state.inventories.find("bag:donor");bag.lots.push_back({"lot:9","grain",{},9,own,{}});bag.lots.push_back({"lot:1","grain",{},5,own,{}});bag.lots.push_back({"lot:2","grain",{},100,public_owner,{}});CommonStore c(state,catalog);InheritancePersonalEntitlement e;e.declaration_id="family_bequest:10";e.acceptance_fact_id="family_inheritance:11";e.death_fact_id="family_death:12";e.donor_actor_id="donor";e.beneficiary_actor_id="beneficiary";e.source_wallet_id="cash:donor";e.source_inventory_id="bag:donor";e.money_remaining=30;e.remaining_lots={{"lot:1","grain",3,{}}};InheritancePersonalSelection selected;selected.money=20;selected.lots={{"lot:1","grain",2,{}}};InheritancePrivateClearanceRead clear=[](const StableId&,const StableId&,const StableId&,Integer,const StableId&){return common_success();};auto original=encode_common_state(c.state());auto quote=preview_inheritance_personal_assets(c,e,selected,clear);check(quote.ok,"exact remaining assets unavailable");check(compare_boundary(original,encode_common_state(c.state())).exact(),"quote wrote assets/RNG/ID");check(!preview_inheritance_personal_assets(c,e,selected,{}).ok,"missing responsibility history treated clear");InheritancePrivateClearanceRead blocked=[](const StableId&,const StableId&,const StableId&,Integer,const StableId&){return common_failure("ActorDebtPending");};check(!preview_inheritance_personal_assets(c,e,selected,blocked).ok,"pending debt ignored");auto wrong=selected;wrong.lots[0].lot_id="lot:9";check(!preview_inheritance_personal_assets(c,e,wrong,clear).ok,"new same item substituted old lot");wrong=selected;wrong.money=31;check(!preview_inheritance_personal_assets(c,e,wrong,clear).ok,"bequest money cap exceeded");wrong=selected;wrong.lots[0].quantity=4;check(!preview_inheritance_personal_assets(c,e,wrong,clear).ok,"original lot cap exceeded");c.state().inventories.find("bag:donor")->lots[1].reserved_by="action:held";check(!preview_inheritance_personal_assets(c,e,selected,clear).ok,"reserved original lot transferred");c.state().inventories.find("bag:donor")->lots[1].reserved_by.clear();c.state().actors.find("beneficiary")->location=SettlementLocation{"town","shore"};check(!preview_inheritance_personal_assets(c,e,selected,clear).ok,"remote personal belongings teleported");c.state().actors.find("beneficiary")->location=SettlementLocation{"town","home"};auto stale=quote.value;stale.identity.execution_epoch++;check(!inheritance_personal_asset_recipe(c,e,stale,clear).ok,"cold old asset quote survived");auto changed=e;changed.money_remaining=10;check(!inheritance_personal_asset_recipe(c,changed,quote.value,clear).ok,"already settled cap ignored");c.state().wallets.find("cash:donor")->balance=99;check(!inheritance_personal_asset_recipe(c,e,quote.value,clear).ok,"same revision changed balance accepted");c.state().wallets.find("cash:donor")->balance=100;auto recipe=inheritance_personal_asset_recipe(c,e,quote.value,clear);check(recipe.ok,"fresh exact recipe refused");auto failed=recipe.value;failed.operations.push_back(WalletDelta{"cash:beneficiary",-9999,true});check(!c.apply_resources(failed).ok&&compare_boundary(original,encode_common_state(c.state())).exact(),"late recipe failure left money/lots/IDs");check(c.apply_resources(recipe.value).ok,"Common recipe failed");check(c.wallet("cash:donor")->balance==80&&c.wallet("cash:beneficiary")->balance==30,"money not conserved");const auto& source=c.inventory("bag:donor")->lots;check(source.size()==3&&source[0].id=="lot:9"&&source[0].quantity==9&&source[1].id=="lot:1"&&source[1].quantity==3&&source[2].id=="lot:2"&&source[2].quantity==100&&source[2].owner.kind==Owner::Kind::organization,"original/public batches changed incorrectly");const auto& target=c.inventory("bag:beneficiary")->lots;check(target.size()==1&&target[0].quantity==2&&target[0].item_id=="grain"&&target[0].owner.kind==Owner::Kind::actor&&target[0].owner.id=="beneficiary"&&target[0].reserved_by==ReservationRef{},"new private lot ownership wrong");check(!inheritance_personal_asset_recipe(c,e,quote.value,clear).ok,"same resources replayed quote");std::cout<<"INHERITANCE_PERSONAL_ASSETS "<<checks<<" checks 0 failures\n";return 0;}catch(const std::exception& e){std::cerr<<"INHERITANCE_PERSONAL_ASSETS "<<checks<<" checks 1 failure: "<<e.what()<<'\n';return 1;}}
